        />
        <span class="cursor-pointer" @click="toggleSearchMode" title="Toggle search mode" v-if="filter">
          <i :class="searchMode === 'content' ? 'fa-solid fa-file-lines' : 'fa-solid fa-magnifying-glass'"></i>
