    def search_files(self, search: str, search_path: str = None, page: int = 0, page_size: int = 50, raw_search: bool = False) -> dict:
        """
        Search for files whose paths contain the search pattern.

        When raw_search is False, only searches files indexed in the knowledge base.
        When raw_search is True, performs a full filesystem search.
        Optionally limits search to a specific subdirectory.

        Args:
            search: Substring pattern to search for in file paths.
            search_path: Optional subdirectory path (relative to project root) to limit search scope.
                        If None, searches entire project. Must be within project root.
            page: Page number (0-indexed, default 0).
            page_size: Number of results per page (default 50).
            raw_search: If True, search all files. If False, search only indexed knowledge base files (default False).

        Returns:
            Dict with page info, total_files count, and paginated files list.
        """
        import re

        # Determine the search root directory
        if search_path:
            search_root = self.get_project_file_path(search_path)
            # Verify it's a directory
            if not os.path.isdir(search_root):
                return {"page": page, "total_files": 0, "page_size": page_size, "files": []}
        else:
            search_root = self.settings.abs_project_path

        matching_files = []

        if raw_search:
            # Original filesystem walk approach
            for root, dirs, files in os.walk(search_root):
                # Skip .git directory
                if ".git" in dirs:
                    dirs.remove(".git")

                for file in files:
                    file_path = os.path.join(root, file)
                    # Get relative path from project root for matching
                    try:
                        rel_path = os.path.relpath(file_path, self.settings.abs_project_path)
                    except ValueError:
                        continue

                    # Check if search pattern matches the relative path
                    if search.lower() in rel_path.lower():
                        matching_files.append(self.parse_file_line(rel_path, self.settings.abs_project_path))
        else:
            # Use knowledge base indexed sources
            try:
                knowledge = self.session.get_knowledge()
                all_sources = knowledge.get_db().get_all_sources()

                # Compile case-insensitive regex pattern
                pattern = re.compile(re.escape(search), re.IGNORECASE)

                for source_path in all_sources.keys():
                    # Filter by search_path if specified
                    if search_path:
                        try:
                            rel_to_search_root = os.path.relpath(source_path, search_root)
                            if rel_to_search_root.startswith(".."):
                                continue
                        except ValueError:
                            continue

                    # Check if search pattern matches the source path
                    if pattern.search(source_path):
                        try:
                            rel_path = os.path.relpath(source_path, self.settings.abs_project_path)
                            matching_files.append(self.parse_file_line(rel_path, self.settings.abs_project_path))
                        except ValueError:
                            continue
            except Exception as ex:
                logger.warning("Could not use knowledge base for search_files, falling back to filesystem: %s", ex)
                # Fallback to filesystem search
                for root, dirs, files in os.walk(search_root):
                    if ".git" in dirs:
                        dirs.remove(".git")

                    for file in files:
                        file_path = os.path.join(root, file)
                        try:
                            rel_path = os.path.relpath(file_path, self.settings.abs_project_path)
                        except ValueError:
                            continue

                        if search.lower() in rel_path.lower():
                            matching_files.append(self.parse_file_line(rel_path, self.settings.abs_project_path))

        # Sort by file path
        matching_files.sort(key=lambda x: x["file_path"])

        # Calculate pagination
        total_files = len(matching_files)
        page_start = page * page_size
        page_end = page_start + page_size
        page_results = matching_files[page_start:page_end]

        return {
            "page": page,
            "total_files": total_files,
            "page_size": page_size,
            "files": page_results
        }

    def search_files_content(self, query: str, search_path: str = None, page: int = 0, page_size: int = 50, case_sensitive: bool = False, raw_search: bool = False) -> dict:
