                "total_matches": 0,
                "page_size": page_size,
                "results": []
            }
    else:
        search_root = self.settings.abs_project_path

    search_pattern = query if case_sensitive else query.lower()
    # Compile regex for pattern matching
    regex_pattern = re.compile(re.escape(search_pattern), re.IGNORECASE if not case_sensitive else 0)
    matching_results = []

    if raw_search:
        # Original filesystem walk approach
        for root, dirs, files in os.walk(search_root):
            # Skip .git directory
            if ".git" in dirs:
                dirs.remove(".git")

            for file in files:
                file_path = os.path.join(root, file)

                try:
                    rel_path = os.path.relpath(file_path, self.settings.abs_project_path)
                except ValueError:
                    continue

                # Try to read file content (skip binary files)
                try:
                    with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
                        content = f.read()
                except (IOError, OSError):
                    continue

                # Search in content
                search_content = content if case_sensitive else content.lower()

                if search_pattern in search_content:
                    # Count matches and extract context lines
                    lines = content.split("\n")
                    matches = []

                    for line_num, line in enumerate(lines, 1):
                        line_search = line if case_sensitive else line.lower()
                        if regex_pattern.search(line_search):
                            matches.append({
                                "line_number": line_num,
                                "line_content": line.strip(),
                                "match_count": len(regex_pattern.findall(line_search))
                            })

                    if matches:
                        file_info = self.get_file_info(file_path)
                        matching_results.append({
                            "file_path": file_path,
                            "rel_path": rel_path,
                            "match_count": len(matches),
                            "matches": matches,
                            **file_info
                        })
    else:
        # Use knowledge base indexed sources
        try:
            knowledge = self.session.get_knowledge()
            all_sources = knowledge.get_db().get_all_sources()

            for source_path in all_sources.keys():
                # Filter by search_path if specified
                if search_path:
                    try:
                        rel_to_search_root = os.path.relpath(source_path, search_root)
                        if rel_to_search_root.startswith(".."):
                            continue
                    except ValueError:
                        continue

                # Try to read file content (skip binary files)
                try:
                    with open(source_path, "r", encoding="utf-8", errors="ignore") as f:
                        content = f.read()
                except (IOError, OSError):
                    continue

                # Search in content
                search_content = content if case_sensitive else content.lower()

                if regex_pattern.search(search_content):
                    # Count matches and extract context lines
                    lines = content.split("\n")
                    matches = []

                    for line_num, line in enumerate(lines, 1):
                        line_search = line if case_sensitive else line.lower()
                        if regex_pattern.search(line_search):
                            matches.append({
                                "line_number": line_num,
                                "line_content": line.strip(),
                                "match_count": len(regex_pattern.findall(line_search))
                            })

                    if matches:
                        try:
                            rel_path = os.path.relpath(source_path, self.settings.abs_project_path)
                        except ValueError:
                            rel_path = source_path

                        file_info = self.get_file_info(source_path)
                        matching_results.append({
                            "file_path": source_path,
                            "rel_path": rel_path,
                            "match_count": len(matches),
                            "matches": matches,
                            **file_info
                        })
        except Exception as ex:
            logger.warning("Could not use knowledge base for search_files_content, falling back to filesystem: %s", ex)
            # Fallback to filesystem search
            for root, dirs, files in os.walk(search_root):
                if ".git" in dirs:
                    dirs.remove(".git")

                for file in files:
                    file_path = os.path.join(root, file)

                    try:
                        rel_path = os.path.relpath(file_path, self.settings.abs_project_path)
                    except ValueError:
                        continue

                    try:
                        with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
                            content = f.read()
                    except (IOError, OSError):
                        continue

                    search_content = content if case_sensitive else content.lower()

                    if regex_pattern.search(search_content):
                        lines = content.split("\n")
                        matches = []

                        for line_num, line in enumerate(lines, 1):
                            line_search = line if case_sensitive else line.lower()
                            if regex_pattern.search(line_search):
                                matches.append({
                                    "line_number": line_num,
                                    "line_content": line.strip(),
                                    "match_count": len(regex_pattern.findall(line_search))
                                })

                        if matches:
                            file_info = self.get_file_info(file_path)
                            matching_results.append({
                                "file_path": file_path,
                                "rel_path": rel_path,
                                "match_count": len(matches),
                                "matches": matches,
                                **file_info
                            })

    # Sort by number of matches (descending) then by file path
    matching_results.sort(key=lambda x: (-x["match_count"], x["rel_path"]))

    # Calculate pagination
    total_files = len(matching_results)
    total_matches = sum(r["match_count"] for r in matching_results)
    page_start = page * page_size
    page_end = page_start + page_size
    page_results = matching_results[page_start:page_end]

    return {
        "page": page,
        "total_files": total_files,
        "total_matches": total_matches,
        "page_size": page_size,
        "results": page_results
    }
